// PORTAO 2 (trava de bancada): sem BT2_BANCADA='1' na aba, o simulador NAO liga nem comanda o PLC.
if (String(env.get('BT2_BANCADA') || '0') !== '1') { msg.statusCode = 404; msg.payload = { ok: false, erro: 'simulador de bancada desligado (BT2_BANCADA != 1 na aba)' }; return [null, msg]; }
// Entrada: POST /simulador/dse  body {ligado:true|false}   (chamado pelo botao "Ligar/Desligar gerador (Demo)" do HTML)
// Saida 1 -> s7 out (escritas no PLC)   Saida 2 -> HTTP response
const b = msg.payload || {};
if (typeof b.ligado !== 'boolean') {
  msg.statusCode = 400;
  msg.payload = { ok: false, erro: 'ligado deve ser true/false' };
  return [null, msg];
}
flow.set('simLigado', b.ligado);
let w;
if (b.ligado) {
  w = [
    { variable: 'ledManual',  payload: true },   // DB2000 ledManual = gerador em START/operando
    { variable: 'tensaoL1L2', payload: 221.1 },  // mesmos valores padrao do Demo do HTML
    { variable: 'tensaoL2L3', payload: 220.8 },
    { variable: 'tensaoL3L1', payload: 221.3 }
  ];
} else {
  w = [
    { variable: 'ledManual',  payload: false },
    { variable: 'tensaoL1L2', payload: 0 },
    { variable: 'tensaoL2L3', payload: 0 },
    { variable: 'tensaoL3L1', payload: 0 },
    { variable: 'potenciaKw', payload: 0 }
  ];
  const TAB = {"BC56": [5, 5, 5, 5, 5, 4, 4, 4, 4, 4, 4, 4, 3], "BC400": [5, 5, 10, 10, 10, 10, 50, 50, 50, 50, 50, 50, 50], "BC595": [5, 5, 5, 5, 5, 4, 4, 4, 4, 4, 4, 3, 3, 2, 1, 0.5, 0.5, 0.5], "BC550": [5, 5, 5, 5, 5, 25, 50, 50, 100, 100, 100, 100]};
  for (const k in TAB) for (let i = 1; i <= TAB[k].length; i++) w.push({ variable: k + '_Lig' + i, payload: false }); // v5: limpa o feedback simulado dos 4 bancos
}
msg.statusCode = 200;
msg.payload = { ok: true, ligado: b.ligado };
return [w, msg];

// PORTAO 2: so age com a trava de bancada ligada
if (String(env.get('BT2_BANCADA') || '0') !== '1') return null;
// v5 (03/11/2026): os 4 bancos. Entrada: leitura ciclica (s7 in 'all', 200 ms). So age com o gerador SIMULADO ligado (flow 'simLigado').
// 1) <banco>_Lig<i> (sb.ligada) = <banco>_Cb<i> (cb.ligar) -> simula a realimentacao fisica; escreve so quando muda
// 2) potenciaKw = kW sem carga + soma dos kW nominais das chaves comandadas (todos os bancos); escrita no maximo 1x por segundo
if (!flow.get('simLigado')) return null;
const p = msg.payload;
if (!p || typeof p !== 'object') return null;
const TAB = {"BC56": [5, 5, 5, 5, 5, 4, 4, 4, 4, 4, 4, 4, 3], "BC400": [5, 5, 10, 10, 10, 10, 50, 50, 50, 50, 50, 50, 50], "BC595": [5, 5, 5, 5, 5, 4, 4, 4, 4, 4, 4, 3, 3, 2, 1, 0.5, 0.5, 0.5], "BC550": [5, 5, 5, 5, 5, 25, 50, 50, 100, 100, 100, 100]};   // kW por chave, ordem fisica (plc/bt2/gerador/bancos_bt2_v0.2.json)
const BASE = 0.8;   // kW sem carga SIMULADO
const out = [];
let carga = 0;
for (const k in TAB) for (let i = 1; i <= TAB[k].length; i++) {
  const cmd = (p[k + '_Cb' + i] === true);
  if (cmd) carga += TAB[k][i - 1];
  if (p[k + '_Lig' + i] !== cmd) out.push({ variable: k + '_Lig' + i, payload: cmd });
}
const agora = Date.now();
if (agora - (flow.get('simUltPot') || 0) >= 1000) {
  flow.set('simUltPot', agora);
  out.push({ variable: 'potenciaKw', payload: Math.round((BASE + carga + (Math.random() - 0.5) * 0.1) * 100) / 100 });
}
return out.length ? [out] : null;

// PORTAO 3 (D3) - "Nunca confie no cliente": rota de ESCRITA so aceita pedido que veio da PROPRIA tela e em JSON.
// CORS sozinho NAO protege (o browser envia o POST mesmo assim); por isso o servidor confere Origin/Referer e Content-Type.
// Origem permitida = mesmo host da pagina (cabecalho Host) ou item de BT2_ORIGENS_OK (variavel da ABA, ex.: http://servidor:1880,null).
const h = (msg.req && msg.req.headers) || {};
const host = String(h.host || '').toLowerCase();
const extras = String(env.get('BT2_ORIGENS_OK') || '').split(',').map(s => s.trim().toLowerCase()).filter(Boolean);
const hostDe = u => { try { return new URL(String(u)).host.toLowerCase(); } catch (e) { return null; } };
const origemDe = u => { try { return new URL(String(u)).origin.toLowerCase(); } catch (e) { return null; } };
let motivo = null;
if (h.origin !== undefined) {
  const o = String(h.origin).toLowerCase();
  if (!((host && hostDe(o) === host) || extras.includes(o))) motivo = 'origem_nao_permitida';
} else if (h.referer !== undefined) {
  const r = origemDe(h.referer);
  if (!((host && hostDe(h.referer) === host) || (r && extras.includes(r)))) motivo = 'origem_nao_permitida';
} else {
  motivo = 'sem_origem';
}
if (!motivo && !/^application\/json\s*(;|$)/i.test(String(h['content-type'] || ''))) motivo = 'content_type_invalido';
if (motivo) {
  node.warn('D3 bloqueado: ' + motivo + ' | ' + String((msg.req && msg.req.method) || '') + ' ' + String((msg.req && msg.req.url) || '').slice(0, 80) + ' | origin=' + String(h.origin || h.referer || '-').slice(0, 80));
  msg.statusCode = 403;
  msg.payload = { ok: false, codigo: 'D3_' + motivo, erro: 'pedido recusado: so e aceito da propria tela do medidor, em JSON (' + motivo + ')' };
  return [null, msg];
}
return [msg, null];
